// Blog pages are generated by scripts/blog/engine.js and then hand-maintained,
// so the colour layer is applied here, idempotently, on top of whatever is there:
//   /blog/            every card gets its subject (data-subject) and a thumbnail
//   /blog/<slug>/     the article gets its subject and a cover plate under the title
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { subjectOfPost } = require('./art.cjs');

const subjectFromTags = (tags) => subjectOfPost({ tags });

function tagIndex(html) {
  html = html.replace(/<a\b[^>]*class="featured-card"[^>]*>/g, (open) => {
    if (/data-subject=/.test(open)) return open;
    const tags = ((open.match(/data-tags="([^"]*)"/) || [])[1] || '').split(',').filter(Boolean);
    return open.replace(/class="featured-card"/, `class="featured-card" data-subject="${subjectFromTags(tags)}"`);
  });
  return html.replace(/<a\b[^>]*class="blog-card"[^>]*>[\s\S]*?<\/a>/g, (card) => {
    const slug = (card.match(/href="\/blog\/([^"/]+)\/"/) || [])[1];
    const tags = ((card.match(/data-tags="([^"]*)"/) || [])[1] || '').split(',').filter(Boolean);
    if (!slug) return card;
    let out = card;
    if (!/data-subject=/.test(out)) out = out.replace(/class="blog-card"/, `class="blog-card" data-subject="${subjectFromTags(tags)}"`);
    if (!/class="blog-card-img"/.test(out)) out = out.replace(/(<a\b[^>]*>)/, `$1<div class="blog-card-img"><img class="default-thumb" src="/assets/blog/${slug}.svg" alt="" width="1200" height="630" loading="lazy" decoding="async"></div>`);
    return out;
  });
}

function tagArticle(html, slug) {
  const tags = [...html.matchAll(/<meta\s+property="article:tag"\s+content="([^"]*)"/g)].map((m) => m[1]);
  const subject = subjectFromTags(tags);
  let out = html;
  if (!/<article class="article-container"[^>]*data-subject=/.test(out)) out = out.replace(/<article class="article-container"/, `<article class="article-container" data-subject="${subject}"`);
  if (!out.includes('<!--cover-->') && /<div class="article-divider">/.test(out)) {
    const fig = `<!--cover--><figure class="article-plate plate"><img src="/assets/blog/${slug}.svg" alt="" width="1200" height="630" decoding="async" fetchpriority="high"></figure><!--/cover-->`;
    out = out.replace(/<div class="article-divider">/, `${fig}\n<div class="article-divider">`);
  }
  return out;
}

export function tagBlog(html, urlPath) {
  if (urlPath === '/blog/') return tagIndex(html);
  const m = urlPath.match(/^\/blog\/([^/]+)\/$/);
  if (m) return tagArticle(html, m[1]);
  return html;
}
